package cn.local.rainreminder;

import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;
import java.io.*;import java.net.*;import org.json.*;

/** Only the current account's public display name and avatar are cached locally. */
final class AccountProfile {
 static boolean busy;static int generation;
 static File avatar(Context c,boolean custom){return new File(c.getFilesDir(),custom?"profile-custom.png":"profile-rain.png");}
 static String name(Context c){String custom=Store.prefs(c).getString("profileNickname","").trim();return custom.isEmpty()?Store.prefs(c).getString("rainProfileName",""):custom;}
 static boolean custom(Context c){return !Store.prefs(c).getString("profileNickname","").trim().isEmpty()||avatar(c,true).exists();}
 static synchronized void clear(Context c){generation++;Store.prefs(c).edit().remove("rainProfileId").remove("rainProfileName").remove("rainProfileAvatar").remove("rainProfileAt").remove("profileNickname").apply();avatar(c,true).delete();avatar(c,false).delete();}
 static synchronized void reset(Context c){Store.prefs(c).edit().remove("profileNickname").apply();avatar(c,true).delete();}
 static JSONObject parse(JSONObject response)throws Exception{if(response.optInt("errcode",-1)!=0)throw new IOException("请先确认雨课堂登录");JSONArray data=response.optJSONArray("data");JSONObject user=data==null?null:data.optJSONObject(0);if(user==null||user.optString("user_id").isEmpty())throw new IOException("暂未读取到雨课堂资料");return user;}
 static synchronized boolean accept(Context c,JSONObject user,int token)throws Exception{if(token!=generation)return false;String id=user.getString("user_id"),old=Store.prefs(c).getString("rainProfileId","");if(!old.isEmpty()&&!id.equals(old)){reset(c);avatar(c,false).delete();}String url=user.optString("avatar","");if(!url.startsWith("https://"))url="";Store.prefs(c).edit().putString("rainProfileId",id).putString("rainProfileName",user.optString("name","").trim()).putString("rainProfileAvatar",url).putLong("rainProfileAt",System.currentTimeMillis()).apply();return true;}
 static void refresh(Context context,boolean force,java.util.function.Consumer<String> done){Context c=context.getApplicationContext();final int token;synchronized(AccountProfile.class){if(busy){if(done!=null)new Handler(Looper.getMainLooper()).post(()->done.accept("正在同步资料，请稍候"));return;}if(!force&&System.currentTimeMillis()-Store.prefs(c).getLong("rainProfileAt",0)<3600000)return;busy=true;token=generation;}
  new Thread(()->{String message="已同步雨课堂资料";try{JSONObject user=parse(CourseApi.get("https://changjiang.yuketang.cn/v2/api/web/userinfo"));if(!accept(c,user,token))return;String url=Store.prefs(c).getString("rainProfileAvatar","");if(!url.isEmpty())try{byte[] bytes=download(url);synchronized(AccountProfile.class){if(token==generation)save(c,new ByteArrayInputStream(bytes),false);}}catch(Exception e){message="名字已同步，头像暂未更新，可稍后重试";}}catch(Exception e){message="资料同步失败，请检查网络和登录；已有资料保留";}finally{synchronized(AccountProfile.class){busy=false;}}final String result=message;if(done!=null)new Handler(Looper.getMainLooper()).post(()->done.accept(result));},"rain-account-profile").start();
 }
 static byte[] download(String address)throws Exception{for(int hop=0;hop<4;hop++){URL url=new URL(address);if(!"https".equals(url.getProtocol())||url.getUserInfo()!=null)throw new IOException("头像地址无效");HttpURLConnection connection=(HttpURLConnection)url.openConnection();try{connection.setConnectTimeout(10000);connection.setReadTimeout(10000);connection.setInstanceFollowRedirects(false);int code=connection.getResponseCode();if(code>=300&&code<400){address=new URL(url,connection.getHeaderField("Location")).toString();continue;}if(code!=200)throw new IOException("头像下载失败");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=connection.getInputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){bytes.write(buf,0,n);if(bytes.size()>4*1024*1024)throw new IOException("头像过大");}}return bytes.toByteArray();}finally{connection.disconnect();}}throw new IOException("头像跳转过多");}
 static void save(Context c,InputStream input,boolean custom)throws Exception{save(c,input,custom,-1);}
 static void save(Context c,InputStream input,boolean custom,int token)throws Exception{byte[] bytes;try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){out.write(buffer,0,n);if(out.size()>20*1024*1024)throw new IOException("请选取小于20MB的图片");}bytes=out.toByteArray();}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<=0||options.outHeight<=0)throw new IOException("无法识别这张图片");options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>1024)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap==null)throw new IOException("无法读取图片");int edge=Math.min(bitmap.getWidth(),bitmap.getHeight());Bitmap crop=Bitmap.createBitmap(bitmap,(bitmap.getWidth()-edge)/2,(bitmap.getHeight()-edge)/2,edge,edge);Bitmap small=Bitmap.createScaledBitmap(crop,256,256,true);File target=avatar(c,custom),part=new File(target.getPath()+".part");try(FileOutputStream out=new FileOutputStream(part)){small.compress(Bitmap.CompressFormat.PNG,100,out);}finally{if(small!=crop)small.recycle();if(crop!=bitmap)crop.recycle();bitmap.recycle();}synchronized(AccountProfile.class){if(token>=0&&token!=generation){part.delete();throw new IOException("账号状态已改变，请重新选择");}if(!part.renameTo(target)){part.delete();throw new IOException("保存头像失败");}}}
}
